const allItems = $input.all();
const imageUrls = allItems.map(item => {
  // item.json.Key berisi "sfyp-storage/slide-xxx.jpg" dari respon Supabase
  return "https://xgqsrttpdxiiqknuulwl.supabase.co/storage/v1/object/public/" + item.json.Key;
});

return {
  json: {
    imageUrls: imageUrls
  }
};

// ============================================================
// n8n Code Node — "Slides HTML - Image" v2
// Mode: Run Once for Each Item
// Input: setiap item adalah 1 slide object dari naskah.slides[]
//        + $json.foreignFlowSummary (dari node Fetch Foreign Flow sebelumnya)
// Output: { html: string }
// ============================================================

const s = $json;

// ── Pagination ──────────────────────────────────────────────
const currentSlide = (s.slideIndex !== undefined ? s.slideIndex + 1 : $itemIndex + 1);
const totalCount   = s.totalSlides || 10;

// ── Meta ────────────────────────────────────────────────────
// CARA 1: Kita paksa buat tanggal hari ini secara otomatis (misal: "Jumat, 18 September 2026")
const today = new Date();
const dateStr = today.toLocaleDateString('id-ID', { 
  weekday: 'long', 
  day: 'numeric', 
  month: 'long', 
  year: 'numeric', 
  timeZone: 'Asia/Jakarta' 
});

const badgeText = s.badgeText || 'OPEN';
const handle    = s.handle || '@sahamfyp';

// ── Foreign Flow Summary (dari node sebelumnya jika ada) ────
const ff = s.foreignFlowSummary || {};
const ffNet     = ff.net_foreign_flow || null;   
const ffBuy     = ff.net_buy || null;
const ffSell    = ff.net_sell || null;
const ffIsInflow = ff.is_inflow === true;

// ── CSS Base Styles ─────────────────────────────────────────
function buildBaseStyles() {
  return `<style>
    @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      width: 1080px; height: 1350px;
      background: #F8F6F0;
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: #14182B; overflow: hidden;
    }
    .slide {
      width: 1080px; height: 1350px;
      padding: 44px 60px 38px 60px;
      display: flex; flex-direction: column;
      background: #F8F6F0;
    }
    .top-header {
      display: flex; justify-content: space-between; align-items: center;
      padding-bottom: 20px; border-bottom: 2px solid rgba(20,24,43,0.1);
      margin-bottom: 2px; flex-shrink: 0;
    }
    .handle-tag { font-weight: 800; font-size: 24px; color: #14182B; display: flex; align-items: center; gap: 12px; }
    .badge-pill { background: #14182B; color: #FFF; font-size: 15px; font-weight: 900; padding: 4px 16px; border-radius: 20px; letter-spacing: 1px; text-transform: uppercase; }
    .brand-title { font-weight: 800; font-size: 22px; color: #64748B; letter-spacing: 0.3px; }
    .bottom-footer {
      display: flex; justify-content: space-between; align-items: center;
      border-top: 2px solid rgba(20,24,43,0.1); padding-top: 16px;
      flex-shrink: 0; margin-top: 4px;
    }
    .date-tag { font-size: 21px; font-weight: 700; color: #64748B; display: flex; align-items: center; gap: 8px; }
    .page-badge { background: #14182B; color: #FFF; font-size: 21px; font-weight: 900; padding: 8px 22px; border-radius: 22px; }

    /* Main body */
    .main-body {
      flex: 1; display: flex; flex-direction: column;
      justify-content: flex-start;
      padding: 28px 0 14px 0;
      gap: 16px; overflow: hidden; min-height: 0;
    }

    .title { font-size: 46px; font-weight: 900; line-height: 1.2; color: #14182B; }
    .subtitle { font-size: 24px; font-weight: 600; color: #64748B; margin-top: -4px; line-height: 1.4; }

    .card-box { background: #FFFFFF; border-radius: 22px; padding: 22px 26px; box-shadow: 0 8px 24px -6px rgba(0,0,0,0.07); border: 1px solid rgba(0,0,0,0.04); }

    .ticker-badge { background: #14182B; color: #F2A93B; font-weight: 900; display: inline-block; }
    .sector-badge { background: #E2E8F0; color: #475569; font-weight: 700; }
    .tag-list { display: flex; flex-wrap: wrap; gap: 8px; }
    .tag-item { background: #FFFBEB; border: 1px solid #FDE68A; color: #D97706; font-weight: 700; border-radius: 8px; }

    .grid-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    .narasi-box { background: rgba(242,169,59,0.12); border-left: 5px solid #F2A93B; padding: 16px 20px; border-radius: 12px; font-size: 20px; line-height: 1.5; color: #14182B; }

    .matrix-grid { display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; gap: 14px; flex: 1; min-height: 0; }
    .matrix-cell { border-radius: 20px; padding: 20px 22px; display: flex; flex-direction: column; }
    .matrix-cell.q1 { background: rgba(76,175,125,0.12); border: 2px solid #4CAF7D; }
    .matrix-cell.q2 { background: rgba(242,169,59,0.12); border: 2px solid #F2A93B; }
    .matrix-cell.q3 { background: rgba(245,158,11,0.12); border: 2px solid #F59E0B; }
    .matrix-cell.q4 { background: rgba(228,87,46,0.12); border: 2px solid #E4572E; }
    .q-title { font-size: 20px; font-weight: 800; margin-bottom: 4px; }
    .q1 .q-title { color: #2E7D32; } .q2 .q-title { color: #D97706; }
    .q3 .q-title { color: #B45309; } .q4 .q-title { color: #C2410C; }

    .ticker-chip-list { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 8px; }
    .ticker-chip { background: #14182B; color: #FFF; font-weight: 900; font-size: 22px; padding: 10px 20px; border-radius: 12px; }
    .empty-text { font-size: 17px; color: #94A3B8; font-style: italic; }

    .table-list { display: flex; flex-direction: column; gap: 6px; }
    .table-row { display: flex; justify-content: space-between; align-items: center; font-size: 18px; padding: 9px 14px; background: rgba(20,24,43,0.05); border-radius: 10px; font-weight: 700; }
  </style>`;
}

// ── Template Builder ─────────────────────────────────────────
let bodyContent = '';
const template = String(s.template || '').toLowerCase().trim();

switch (template) {

  // ── COVER ──────────────────────────────────────────────────
  case 'cover': {
    bodyContent = `
      <div class="main-body" style="justify-content:center;align-items:center;text-align:center;gap:28px;padding-top:134px;">
        <div style="align-self:flex-start;">
          <span style="background:#14182B;color:#F2A93B;font-size:20px;font-weight:900;padding:8px 22px;border-radius:30px;">DAILY MARKET BRIEF 🚀</span>
        </div>
        <div>
          <h1 class="title" style="font-size:58px;line-height:1.15;">Key Catalyst & Watchlist Saham Hari Ini</h1>
          <p class="subtitle" style="font-size:26px;margin-top:16px;">Bedah Berita, Aksi Korporasi & Sinyal Teknikal Pilihan</p>
        </div>
        <div class="card-box" style="background:#14182B;color:#FFF;display:flex;justify-content:space-around;padding:30px;margin-top:8px;width:100%;">
          <div style="text-align:center;">
            <div style="font-size:42px;font-weight:900;color:#F2A93B;">${s.newsCount || 0}</div>
            <div style="font-size:18px;color:#94A3B8;font-weight:600;">Berita Pilihan</div>
          </div>
          <div style="width:1px;background:rgba(255,255,255,0.15);"></div>
          <div style="text-align:center;">
            <div style="font-size:42px;font-weight:900;color:#F2A93B;">${s.watchlistCount || 0}</div>
            <div style="font-size:18px;color:#94A3B8;font-weight:600;">Emiten Radar</div>
          </div>
        </div>
      </div>`;
    break;
  }

  // ── TLDR ───────────────────────────────────────────────────
  case 'tldr': {
    const cards = s.tldrCards || [];

    const marketCards   = cards.filter(c => c.section === 'kondisiMarket' || (!c.section && (c.text.includes('IHSG') || c.text.toLowerCase().includes('gainer') || c.text.toLowerCase().includes('loser') || c.text.toLowerCase().includes('asing'))));
    const fillingsCards = cards.filter(c => c.section === 'fillings');
    const katalisCards  = cards.filter(c => c.section === 'katalis' || (!c.section && !c.text.toLowerCase().includes('watchlist') && !c.text.includes('IHSG') && !c.text.toLowerCase().includes('gainer') && !c.text.toLowerCase().includes('loser') && !c.text.toLowerCase().includes('asing')));
    const watchlistCard = cards.find(c => c.section === 'watchlist' || c.text.toLowerCase().includes('watchlist'));

    const watchlistText = watchlistCard ? watchlistCard.text.replace(/watchlist:/i, '').trim() : '';
    const tickerChips   = watchlistText.split(/[,\s]+/).filter(t => t.replace('.JK','').length >= 2 && t.replace('.JK','').length <= 6);

    const ffNetStr = ffNet
      ? `🌍 Foreign Flow: ${ffIsInflow ? '🟢' : '🔴'} ${ffNet}`
      : '';

    const renderSection = (title, icon, color, bg, items) => items.length === 0 ? '' : `
      <div class="card-box" style="padding:14px 20px;background:${bg};border:1px solid ${color};box-shadow:none;">
        <div style="font-size:16px;font-weight:900;color:${color};margin-bottom:9px;text-transform:uppercase;letter-spacing:0.5px;">${icon} ${title}</div>
        <div style="display:flex;flex-direction:column;gap:7px;">
          ${items.map(k => `<div style="font-size:18px;font-weight:600;color:#1E293B;display:flex;gap:8px;align-items:flex-start;"><span style="color:${color};font-weight:900;flex-shrink:0;">•</span><span>${k.text}</span></div>`).join('')}
          ${title.includes('Market') && ffNetStr ? `<div style="font-size:18px;font-weight:600;color:#1E293B;display:flex;gap:8px;align-items:flex-start;"><span style="font-weight:900;flex-shrink:0;">•</span><span>${ffNetStr}</span></div>` : ''}
        </div>
      </div>`;

    bodyContent = `
      <div class="main-body" style="gap:11px;padding-top:106px;">
        <h1 class="title" style="font-size:40px; margin-bottom: 26px;">📌 ${s.title || 'TL;DR — Ringkasan Hari Ini'}</h1>
        ${renderSection('Kondisi Market Kemarin', '📈', '#14182B', 'rgba(20,24,43,0.06)', marketCards)}
        ${renderSection('Fillings & Keterbukaan', '📋', '#2563EB', 'rgba(37,99,235,0.07)', fillingsCards)}
        ${renderSection('Katalis Hari Ini', '🔥', '#D97706', 'rgba(217,119,6,0.08)', katalisCards)}
        <div class="card-box" style="padding:14px 20px;background:#14182B;color:#FFF;box-shadow:none;">
          <div style="font-size:16px;font-weight:900;color:#F2A93B;margin-bottom:9px;text-transform:uppercase;letter-spacing:0.5px;">🎯 Watchlist Saham Hari Ini</div>
          <div class="ticker-chip-list">
            ${tickerChips.length > 0
              ? tickerChips.map(t => `<span class="ticker-chip" style="background:#F2A93B;color:#14182B;font-size:24px;padding:8px 22px;">${t.replace('.JK','')}</span>`).join('')
              : `<span style="font-size:18px;color:#94A3B8;">${watchlistText || 'Pantau update berikutnya'}</span>`
            }
          </div>
        </div>
      </div>`;
    break;
  }

  // ── MARKET ─────────────────────────────────────────────────
  case 'market': {
    const ihsg      = s.ihsg || {};
    const ihsgPrice = ihsg.price ? Number(ihsg.price).toLocaleString('id-ID') : '-';
    const chgPct    = Number(ihsg.changePct || 0);
    const ihsgChg   = `${chgPct >= 0 ? '+' : ''}${chgPct.toFixed(2)}%`;
    const ihsgColor = chgPct >= 0 ? '#16A34A' : '#DC2626';
    const ihsgArrow = chgPct >= 0 ? '▲' : '▼';
    const ihsgBg    = chgPct >= 0 ? '#DCFCE7' : '#FEE2E2';

    const gainers = (s.topGainers || []).slice(0, 5).map(g => {
      const sym  = (g.symbol || g.ticker || '').replace('.JK','');
      const name = (g.name || g.companyName || sym).slice(0, 18);
      const chg  = Number(g.changePct || 0).toFixed(2);
      return `<div class="table-row"><span><b>${sym}</b> <span style="font-size:15px;color:#64748B;font-weight:600;">${name}</span></span><span style="color:#16A34A;">+${chg}%</span></div>`;
    }).join('');

    const losers = (s.topLosers || []).slice(0, 5).map(l => {
      const sym  = (l.symbol || l.ticker || '').replace('.JK','');
      const name = (l.name || l.companyName || sym).slice(0, 18);
      const chg  = Number(l.changePct || 0).toFixed(2);
      return `<div class="table-row"><span><b>${sym}</b> <span style="font-size:15px;color:#64748B;font-weight:600;">${name}</span></span><span style="color:#DC2626;">${chg}%</span></div>`;
    }).join('');

    const ffSection = ffNet ? `
      <div class="card-box" style="padding:16px 22px;box-shadow:none;border:1.5px solid ${ffIsInflow ? '#4CAF7D' : '#E4572E'};background:${ffIsInflow ? 'rgba(76,175,125,0.08)' : 'rgba(228,87,46,0.08'};">
        <div style="font-size:18px;font-weight:800;color:#64748B;margin-bottom:10px;">🌍 Foreign Flow Kemarin</div>
        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;text-align:center;">
          <div>
            <div style="font-size:13px;font-weight:700;color:#94A3B8;margin-bottom:4px;text-transform:uppercase;">Net Total</div>
            <div style="font-size:20px;font-weight:900;color:${ffIsInflow ? '#16A34A' : '#DC2626'};">${ffNet}</div>
          </div>
          <div>
            <div style="font-size:13px;font-weight:700;color:#94A3B8;margin-bottom:4px;text-transform:uppercase;">Net Buy</div>
            <div style="font-size:20px;font-weight:900;color:#16A34A;">${ffBuy || '-'}</div>
          </div>
          <div>
            <div style="font-size:13px;font-weight:700;color:#94A3B8;margin-bottom:4px;text-transform:uppercase;">Net Sell</div>
            <div style="font-size:20px;font-weight:900;color:#DC2626;">${ffSell || '-'}</div>
          </div>
        </div>
      </div>` : '';

    bodyContent = `
      <div class="main-body" style="gap:14px;padding-top:108px;padding-bottom:14px;">
        <h1 class="title" style="font-size:40px; margin-bottom: 26px;">📊 ${s.title || 'Kondisi Market Kemarin'}</h1>

        <!-- IHSG Banner -->
        <div class="card-box" style="background:#14182B;color:#FFF;display:flex;justify-content:space-between;align-items:center;padding:22px 30px;">
          <div>
            <div style="font-size:20px;font-weight:800;color:#94A3B8;margin-bottom:4px;">IHSG</div>
            <div style="font-size:40px;font-weight:900;color:#F2A93B;">${ihsgPrice}</div>
          </div>
          <div style="text-align:right;">
            <div style="font-size:28px;font-weight:900;background:${ihsgBg};color:${ihsgColor};padding:8px 20px;border-radius:16px;">${ihsgArrow} ${ihsgChg}</div>
            <!-- MENGGUNAKAN TANGGAL HARI INI JUGA (CARA 1 FIX) -->
            <div style="font-size:15px;color:#94A3B8;margin-top:6px;">${dateStr}</div>
          </div>
        </div>

        <!-- Foreign Flow -->
        ${ffSection}

        <!-- Top Gainers & Losers -->
        <div class="grid-2col">
          <div class="card-box" style="padding:18px 20px;">
            <div style="font-size:20px;font-weight:900;color:#16A34A;margin-bottom:10px;">🚀 TOP GAINERS</div>
            <div class="table-list">${gainers}</div>
          </div>
          <div class="card-box" style="padding:18px 20px;">
            <div style="font-size:20px;font-weight:900;color:#DC2626;margin-bottom:10px;">🔻 TOP LOSERS</div>
            <div class="table-list">${losers}</div>
          </div>
        </div>
      </div>`;
    break;
  }

  // ── STOCK ──────────────────────────────────────────────────
  case 'stock': {
    const fund        = s.fundamentals || {};
    const tech        = s.technical    || {};
    const tldr        = s.tldrSaham    || {};
    const cleanTicker = (s.ticker || 'EMITEN').replace('.JK','');
    const sectorName  = s.sector || fund.sector || 'Sektor';
    const formattedPrice = s.hargaTerakhir ? `Rp ${Number(s.hargaTerakhir).toLocaleString('id-ID')}` : '';
    const displaySource  = s.sumberBerita || 'Sector.app News';

    const perVs = fund.perSector ? ` (vs ${fund.perSector})` : '';
    const pbvVs = fund.pbvSector ? ` (vs ${fund.pbvSector})` : '';
    const roeVs = fund.roeSector ? ` (vs ${fund.roeSector})` : '';

    const signalVibe = tech.narasiVibe || (
      (tech.crossSignal || '').includes('Golden Cross') ? 'MA20 memotong ke atas MA50 — sinyal tren naik.' :
      (tech.crossSignal || '').includes('Death Cross')  ? 'MA20 memotong ke bawah MA50 — sinyal tren turun.' :
      (tech.crossSignal || '').includes('Bullish')      ? 'Harga di atas MA20 & MA50 — tren naik masih berlanjut.' :
      'Belum ada arah yang jelas, pantau pergerakan harga dan volume.'
    );

    const ma20Fmt = tech.ma20 ? Number(tech.ma20).toLocaleString('id-ID') : '-';
    const ma50Fmt = tech.ma50 ? Number(tech.ma50).toLocaleString('id-ID') : '-';

    const newsDescFull = s.newsDescription || s.narasiBerita || s.apa || '';

    bodyContent = `
      <div class="main-body" style="gap:16px;padding-top:108px;padding-bottom:14px;">

        <!-- Header: Ticker + Harga -->
        <div style="margin-bottom: 24px;">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span class="ticker-badge" style="font-size:50px;padding:6px 26px;border-radius:16px;">${cleanTicker}</span>
            ${formattedPrice ? `<span style="font-size:42px;font-weight:900;color:#D97706;">${formattedPrice}</span>` : ''}
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;">
            <div style="font-size:26px;font-weight:800;color:#14182B;">${s.companyName || ''}</div>
            <span class="sector-badge" style="font-size:17px;padding:6px 18px;border-radius:20px;">Sektor ${sectorName}</span>
          </div>
          ${s.tags && s.tags.length > 0 ? `
            <div class="tag-list" style="margin-top:8px;">
              ${s.tags.map(tg => `<span class="tag-item" style="font-size:15px;padding:4px 12px;">#${tg}</span>`).join('')}
            </div>` : ''}
        </div>

        <!-- News Card -->
        <div class="card-box" style="padding:20px 24px;border-left:6px solid #F2A93B;">
          <div style="font-size:22px;font-weight:900;color:#14182B;line-height:1.35;margin-bottom:10px;">${s.newsTitle || ''}</div>
          <div style="font-size:19px;color:#334155;line-height:1.55;">${newsDescFull}</div>
          ${s.kenapa ? `<div style="font-size:18px;color:#475569;margin-top:8px;line-height:1.5;">💬 ${s.kenapa}</div>` : ''}
          ${s.dampak ? `<div style="font-size:17px;color:#64748B;margin-top:6px;font-style:italic;line-height:1.45;">📌 Dampak: ${s.dampak}</div>` : ''}
          <div style="font-size:14px;font-weight:700;color:#94A3B8;text-align:right;margin-top:10px;">${displaySource}</div>
        </div>

        <!-- Fundamental & Teknikal Grid -->
        <div class="grid-2col">
          <!-- Fundamental -->
          <div class="card-box" style="padding:18px 20px;">
            <div style="font-size:20px;font-weight:900;color:#14182B;margin-bottom:10px;border-bottom:2px solid #F1F5F9;padding-bottom:7px;">📊 Fundamental</div>
            <div style="font-size:17px;display:flex;flex-direction:column;gap:9px;font-weight:600;color:#14182B;">
              <div style="display:flex;justify-content:space-between;align-items:center;">
                <span><b>PER:</b> ${fund.per || '-'}<span style="color:#94A3B8;font-weight:500;font-size:15px;">${perVs}</span></span>
                ${fund.perSignal ? `<span style="font-size:14px;font-weight:700;">${fund.perSignal}</span>` : ''}
              </div>
              <div style="display:flex;justify-content:space-between;align-items:center;">
                <span><b>PBV:</b> ${fund.pbv || '-'}<span style="color:#94A3B8;font-weight:500;font-size:15px;">${pbvVs}</span></span>
                ${fund.pbvSignal ? `<span style="font-size:14px;font-weight:700;">${fund.pbvSignal}</span>` : ''}
              </div>
              <div style="display:flex;justify-content:space-between;align-items:center;">
                <span><b>ROE:</b> ${fund.roe || '-'}<span style="color:#94A3B8;font-weight:500;font-size:15px;">${roeVs}</span></span>
                ${fund.roeSignal ? `<span style="font-size:14px;font-weight:700;">${fund.roeSignal}</span>` : ''}
              </div>
            </div>
            ${fund.narasiFundamental ? `
              <div style="font-size:15px;color:#475569;font-style:italic;margin-top:10px;border-top:1px dashed #E2E8F0;padding-top:8px;line-height:1.5;">
                💡 ${fund.narasiFundamental}
              </div>` : ''}
          </div>
          <!-- Teknikal -->
          <div class="card-box" style="padding:18px 20px;">
            <div style="font-size:20px;font-weight:900;color:#14182B;margin-bottom:10px;border-bottom:2px solid #F1F5F9;padding-bottom:7px;">📈 Teknikal</div>
            <div style="font-size:17px;display:flex;flex-direction:column;gap:9px;font-weight:600;color:#14182B;">
              <div style="display:flex;justify-content:space-between;align-items:center;">
                <span><b>Sinyal:</b></span>
                <span style="color:#F2A93B;font-size:15px;font-weight:900;">${tech.crossSignal || 'Konsolidasi 🟡'}</span>
              </div>
              <div><b>MA20:</b> Rp ${ma20Fmt}</div>
              <div><b>MA50:</b> Rp ${ma50Fmt}</div>
            </div>
            <div style="font-size:15px;color:#475569;font-style:italic;margin-top:10px;border-top:1px dashed #E2E8F0;padding-top:8px;line-height:1.5;">
              💡 ${signalVibe}
            </div>
          </div>
        </div>

        <!-- Key Takeaway -->
        <div class="card-box" style="padding:18px 24px;background:#14182B;color:#FFF;border-radius:20px;">
          <div style="font-size:19px;font-weight:900;color:#F2A93B;margin-bottom:6px;">💡 Key Takeaway:</div>
          <div style="font-size:18px;color:#F8FAFC;line-height:1.5;font-weight:500;">
            ${tldr.swing || tldr.investasi || tldr.dayTrading || tech.trigger || 'Pantau volume dan support MA20 untuk menentukan titik entry optimal.'}
          </div>
        </div>

        ${s.warning ? `<div style="background:rgba(228,87,46,0.12);border:2px solid #E4572E;color:#9A2C12;border-radius:14px;padding:12px 18px;font-size:17px;font-weight:700;display:flex;align-items:center;gap:10px;">⚠️ ${s.warning}</div>` : ''}
      </div>`;
    break;
  }

  // ── MATRIX ─────────────────────────────────────────────────
  case 'matrix': {
    const stocks = s.stocks || [];
    const getChips = q => {
      const tickers = stocks.filter(x => x.quadrant === q).map(x => x.ticker);
      if (!tickers.length) return `<span class="empty-text">Tidak ada emiten</span>`;
      return `<div class="ticker-chip-list">${tickers.map(t => `<span class="ticker-chip" style="font-size:24px;padding:10px 20px;">${t.replace('.JK','')}</span>`).join('')}</div>`;
    };

    bodyContent = `
      <div class="main-body" style="gap:18px;padding-top:108px;padding-bottom:14px;">
        <div style="margin-bottom: 24px;">
          <h1 class="title">🧩 ${s.title || 'Kesimpulan Watchlist Hari Ini'}</h1>
          <div class="subtitle">${s.subtitle || 'Framework: Matrix Fundamental × Teknikal'}</div>
        </div>
        <div class="matrix-grid">
          <div class="matrix-cell q1">
            <div class="q-title">🟢 Q1: Fund ✅ + Tech ✅</div>
            <div style="font-size:13px;color:#2E7D32;font-weight:700;margin-bottom:10px;font-style:italic;">${s.q1Label || 'Cocok: Investasi & Swing Trading'}</div>
            ${getChips('q1')}
          </div>
          <div class="matrix-cell q2">
            <div class="q-title">🟡 Q2: Fund ✅ + Tech ⚠️</div>
            <div style="font-size:13px;color:#D97706;font-weight:700;margin-bottom:10px;font-style:italic;">${s.q2Label || 'Cocok: Value Investing, tunggu teknikal'}</div>
            ${getChips('q2')}
          </div>
          <div class="matrix-cell q3">
            <div class="q-title">🟠 Q3: Fund ⚠️ + Tech ✅</div>
            <div style="font-size:13px;color:#B45309;font-weight:700;margin-bottom:10px;font-style:italic;">${s.q3Label || 'Trading momentum jangka pendek SAJA'}</div>
            ${getChips('q3')}
          </div>
          <div class="matrix-cell q4">
            <div class="q-title">🔴 Q4: Fund ⚠️ + Tech ⚠️</div>
            <div style="font-size:13px;color:#C2410C;font-weight:700;margin-bottom:10px;font-style:italic;">${s.q4Label || 'Hindari dulu, tunggu pemulihan'}</div>
            ${getChips('q4')}
          </div>
        </div>
        ${s.note ? `<div style="font-size:17px;color:#64748B;font-style:italic;">💡 ${s.note}</div>` : ''}
      </div>`;
    break;
  }

  // ── KAMUS ──────────────────────────────────────────────────
  case 'kamus': {
    const kamusItems = s.items || [
      { term: 'PER',                  category: 'fundamental', definition: 'Berapa tahun balik modal dari laba perusahaan.', analogi: 'Beli HP Rp15jt, untung Rp1jt/thn → PER 15x. Makin kecil = makin cepet balik modal!' },
      { term: 'PBV',                  category: 'fundamental', definition: 'Bayar berapa kali lipat dari aset bersih.', analogi: 'PBV < 1 = beli aset di bawah harga buku = diskon! PBV tinggi = bayar premium buat ekspektasi.' },
      { term: 'ROE & DER',            category: 'fundamental', definition: 'Efisiensi modal (ROE) vs beban utang (DER).', analogi: 'ROE tinggi = jago putar modal. DER < 1x = aman. DER > 3x = hati-hati paylater membengkak!' },
      { term: 'MA20 & MA50',          category: 'teknikal',    definition: 'Rata-rata harga 20 & 50 hari — patokan support/resistance.', analogi: 'MA20 = mood pasar bulan ini. MA50 = mood 2.5 bulan. Harga di atas keduanya = on top vibes!' },
      { term: 'Golden & Death Cross', category: 'teknikal',    definition: 'Sinyal pembalikan tren dari perpotongan MA20 vs MA50.', analogi: 'Golden Cross 🚀 = MA20 naik ke atas MA50 (bullish!). Death Cross ☠️ = MA20 turun ke bawah.' },
      { term: 'Foreign Flow',         category: 'teknikal',    definition: 'Arus dana investor asing — net buy (masuk) atau net sell (keluar).', analogi: 'Asing net buy = influencer borong = sentimen positif. Net sell = waspada, tapi jangan langsung panik!' },
    ];

    const fundItems = kamusItems.filter(k => k.category === 'fundamental' || !k.category);
    const techItems = kamusItems.filter(k => k.category === 'teknikal');

    const renderItem = (k, color) => `
      <div class="card-box" style="padding:12px 16px;border-left:4px solid ${color};box-shadow:none;border-radius:14px;">
        <div style="font-size:18px;font-weight:900;color:#14182B;margin-bottom:2px;">${k.term}</div>
        <div style="font-size:14px;color:#64748B;font-weight:600;margin-bottom:5px;">${k.definition}</div>
        <div style="font-size:15px;color:#334155;font-style:italic;line-height:1.4;">💡 ${k.analogi}</div>
      </div>`;

    bodyContent = `
      <div class="main-body" style="gap:12px;padding-top:106px;padding-bottom:14px;">
        <div style="margin-bottom: 28px;">
          <h1 class="title" style="font-size:40px;">📖 ${s.title || 'Kamus Ala Gen Z'}</h1>
