            ${fundItems.map(k => renderItem(k, '#2563EB')).join('')}
          </div>
          <div style="display:flex;flex-direction:column;gap:9px;">
            <div style="font-size:14px;font-weight:900;color:#F2A93B;text-transform:uppercase;letter-spacing:0.6px;padding-bottom:4px;">📈 Teknikal</div>
            ${techItems.map(k => renderItem(k, '#F2A93B')).join('')}
          </div>
        </div>
      </div>`;
    break;
  }

  // ── CTA ────────────────────────────────────────────────────
  case 'cta': {
    bodyContent = `
      <div class="main-body" style="justify-content:center;align-items:center;text-align:center;gap:28px;padding-top:134px;padding-bottom:20px;">
