        <h1 class="title" style="font-size:56px;">${s.title || 'Gimana Menurutmu?'}</h1>
        <p class="subtitle" style="font-size:28px;max-width:800px;color:#334155;">${s.description || 'Drop pendapatmu di kolom komentar! 👇'}</p>
        <div style="background:#14182B;color:#F2A93B;font-size:26px;font-weight:900;padding:16px 40px;border-radius:30px;margin-top:8px;">Follow @sahamfyp 🚀</div>
        ${s.disclaimer ? `<div style="font-size:18px;color:#94A3B8;margin-top:16px;">${s.disclaimer}</div>` : ''}
      </div>`;
    break;
  }

  default: {
    bodyContent = `
      <div class="main-body" style="padding-top:134px;">
        <h1 class="title">${s.title || ''}</h1>
        <p class="subtitle">${s.description || ''}</p>
