parameters.jsCode:
const sessionData = $('SectorTrigger - OPEN').first().json || {};
const naskah = sessionData.naskah || {};
const selection = sessionData.selection || {};
const slides = naskah.slides || [];

// Mengambil data hasil publish dari node sebelumnya
const publishData = $('Publish - Repliz').first().json || {};
const publishResults = publishData.results || [];

const now = new Date();

// Format waktu Indonesia (WIB)
const options = { 
  weekday: 'long', 
  year: 'numeric', 
  month: '2-digit', 
  day: '2-digit', 
  hour: '2-digit', 
  minute: '2-digit',
  timeZone: 'Asia/Jakarta'
};
const waktu = now.toLocaleString('id-ID', options).replace(/\//g, '/');

// Mengambil saham terpilih dari slides
const stockSlides = slides.filter(s => s.template === 'stock');
const selectedList = stockSlides.length > 0 
  ? stockSlides.map(s => `• *${s.ticker}* (${s.companyName || ''})`).join('\n')
  : 'Tidak ada saham terpilih';

// Helper untuk generate URL profil berdasarkan platform
function getProfileUrl(platform, name) {
  const cleanName = (name || '').replace('@', '');
  if (!cleanName) return '#';
  switch (platform.toLowerCase()) {
    case 'instagram': return `https://instagram.com/${cleanName}`;
    case 'twitter': return `https://x.com/${cleanName}`;
    case 'tiktok': return `https://tiktok.com/@${cleanName}`;
    case 'facebook': return `https://facebook.com/${cleanName}`;
    case 'threads': return `https://threads.net/@${cleanName}`;
    case 'telegram': return `https://t.me/${cleanName}`;
    case 'linkedin': return `https://linkedin.com/company/${cleanName}`;
    default: return '#';
  }
}

// Membangun daftar platform yang sukses
let publishList = publishResults
  .filter(r => r.status === 'success')
  .map(r => {
    // Membuat huruf pertama platform menjadi kapital (contoh: instagram -> Instagram)
    const platformName = r.platform.charAt(0).toUpperCase() + r.platform.slice(1);
    const link = getProfileUrl(r.platform, r.accountName);
    return `• ${platformName} : ${link}`;
  })
  .join('\n');

if (!publishList) {
  publishList = "_Tidak ada publikasi yang sukses_";
}

let message = `🚀 *SahamFYP - Market Brief OPEN*\n`;
message += `━━━━━━━━━━━━━━━━━━━━\n`;
message += `🕐 *Waktu* : ${waktu} WIB\n`;
message += `📌 *Judul* : ${slides[0]?.title || 'Market Brief Open'}\n`;
message += `💳 *Credits Used* : ${sessionData.creditsUsed || 0} Credits\n\n`;

message += `🎯 *Watchlist Saham Terpilih (${stockSlides.length})*:\n`;
message += `${selectedList}\n\n`;

message += `📝 *Alasan Seleksi*:\n`;
message += `_${selection.reasoning || 'Katalis korporasi terpilih'}_\n`;
message += `━━━━━━━━━━━━━━━━━━━━\n`;
message += `✨ *Berhasil terbit ke ${publishData.success_count || 0} akun*:\n`;
message += `${publishList}`;

return { json: { message } };
